Mesh<Point, double> result;
std::vector<unsigned> face_vertices;
std::vector<bool> visited_edges(rt.number_of_edges(), false);

for (auto it = rt.finite_edges_begin(); it != rt.finite_edges_end(); ++it) {
    const Edge& e = *it;
    if (is_small_edge(rt, e, threshold)) continue;

    // Get the two incident cells
    RT::Cell_handle c1 = it->first;
    int i1 = it->second;
    RT::Cell_handle c2 = c1->neighbor(i1);
    int i2 = c1->index(c2);

    // Skip if edge is not on the boundary of the power diagram (both cells are finite)
    if (!rt.is_infinite(c1) && !rt.is_infinite(c2)) {
        // Collect the two faces opposite to the edge in each cell
        // Each face is a triangle of three vertices
        for (int j = 0; j < 4; ++j) {
            if (j != i1 && j != i2) {
                face_vertices.push_back(rt.vertex_index(c1->vertex(j)));
            }
        }
        // Add the first face
        result.push_back(face_vertices, rt.segment(e).squared_length());
        face_vertices.clear();

        for (int j = 0; j < 4; ++j) {
            if (j != i2 && j != i1) {
                face_vertices.push_back(rt.vertex_index(c2->vertex(j)));
            }
        }
        // Add the second face
        result.push_back(face_vertices, rt.segment(e).squared_length());
        face_vertices.clear();
    }
}

// Handle infinite cells: for each infinite cell, collect its finite faces
for (auto it = rt.finite_cells_begin(); it != rt.finite_cells_end(); ++it) {
    RT::Cell_handle c = it;
    if (rt.is_infinite(c)) continue;

    for (int i = 0; i < 4; ++i) {
        RT::Cell_handle neighbor = c->neighbor(i);
        if (rt.is_infinite(neighbor)) {
            // This face is on the boundary of the power diagram
            face_vertices.clear();
            for (int j = 0; j < 4; ++j) {
                if (j != i) {
                    face_vertices.push_back(rt.vertex_index(c->vertex(j)));
                }
            }
            // Compute edge length as average of incident edges? Or use squared length of one edge?
            // Use the squared length of one edge of the face
            RT::Segment seg = rt.segment(RT::Edge(c, i, (i+1)%4));
            double edge_sq_len = seg.squared_length();
            result.push_back(face_vertices, edge_sq_len);
        }
    }
}

return result;

